custom_css:
.web-form-wrapper {
  --ca-ink: #16211c;
  --ca-ink-soft: #5c6b64;
  --ca-line: #dfe4e0;
  --ca-accent: #1f4034;
  --ca-accent-soft: #eef2ef;
  --ca-surface: #ffffff;
  --ca-page: #f7f8f6;
  color: var(--ca-ink);
}

.web-form-wrapper .page-header,
.web-form-wrapper .web-form-header {
  border-bottom: 1px solid var(--ca-line);
  padding-bottom: 1rem;
  margin-bottom: 1.75rem;
}

.web-form-wrapper .web-form-head .title,
.web-form-wrapper h1 {
  font-weight: 600;
  letter-spacing: -0.02em;
}

.web-form-wrapper .section-head,
.web-form-wrapper .form-section .section-head {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ca-accent);
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--ca-line);
}

.web-form-wrapper .form-section {
  background: var(--ca-surface);
  border: 1px solid var(--ca-line);
  border-radius: 10px;
  padding: 1.5rem 1.5rem 0.75rem;
  margin-bottom: 1.25rem;
}

.web-form-wrapper .control-label {
  font-weight: 500;
  color: var(--ca-ink);
}

.web-form-wrapper .help-box,
.web-form-wrapper .form-control + .help-box {
  color: var(--ca-ink-soft);
  font-size: 0.8125rem;
  line-height: 1.45;
}

.web-form-wrapper .form-control {
  border: 1px solid var(--ca-line);
  border-radius: 6px;
  background: var(--ca-page);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.web-form-wrapper .form-control:focus {
  border-color: var(--ca-accent);
  background: var(--ca-surface);
  box-shadow: 0 0 0 3px var(--ca-accent-soft);
  outline: none;
}

.web-form-wrapper .btn-primary,
.web-form-wrapper .btn-form-submit {
  background: var(--ca-accent);
  border-color: var(--ca-accent);
  font-weight: 600;
  padding: 0.55rem 1.4rem;
  border-radius: 6px;
}

.web-form-wrapper .btn-primary:hover,
.web-form-wrapper .btn-form-submit:hover {
  background: #163027;
  border-color: #163027;
}

.web-form-wrapper .btn-primary:focus-visible {
  outline: 2px solid var(--ca-accent);
  outline-offset: 2px;
}

.ca-license-warning {
  margin-top: 0.4rem;
  font-size: 0.8125rem;
  color: #8a5a00;
}

@media (max-width: 767px) {
  .web-form-wrapper .form-section {
    padding: 1.1rem 1.1rem 0.4rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .web-form-wrapper .form-control {
    transition: none;
  }
}
